     8	public class DatabaseConfig {
     9	    private static HikariDataSource dataSource;
    10	
    11	    public static void initialize() {
    12	        String dbUrl = System.getenv("DB_URL");
    13	        String dbUser = System.getenv("DB_USER");
    14	        String dbPassword = System.getenv("DB_PASSWORD");
    15	
    16	        if (dbUrl == null || dbUser == null || dbPassword == null) {
    17	            throw new RuntimeException("Database environment variables not set");
    18	        }
    19	
    20	        HikariConfig config = new HikariConfig();
    21	        config.setJdbcUrl(dbUrl);
    22	        config.setUsername(dbUser);
    23	        config.setPassword(dbPassword);
    24	        config.setMaximumPoolSize(10);
    25	
    26	        dataSource = new HikariDataSource(config);
    27	
    28	        createSchema();
    29	    }
    30	
    31	    private static void createSchema() {
    32	        String schema = """
    33	            CREATE TABLE IF NOT EXISTS rooms (
    34	                number INTEGER PRIMARY KEY,
    35	                type VARCHAR(20) NOT NULL,
    36	                capacity INTEGER NOT NULL,
    37	                nightly_rate DECIMAL(10, 2) NOT NULL
    38	            );
    39	
    40	            CREATE TABLE IF NOT EXISTS reservations (
    41	                id BIGSERIAL PRIMARY KEY,
    42	                room_number INTEGER NOT NULL REFERENCES rooms(number),
    43	                guest_name VARCHAR(255) NOT NULL,
    44	                guest_email VARCHAR(255) NOT NULL,
    45	                guest_cpf VARCHAR(20) NOT NULL,
    46	                check_in DATE NOT NULL,
    47	                check_out DATE NOT NULL,
    48	                guests INTEGER NOT NULL,
    49	                rate_plan VARCHAR(20) NOT NULL,
    50	                nights INTEGER NOT NULL,
    51	                subtotal DECIMAL(10, 2) NOT NULL,
    52	                discount DECIMAL(10, 2),
    53	                total DECIMAL(10, 2) NOT NULL,
    54	                status VARCHAR(20) NOT NULL,
    55	                amount_paid DECIMAL(10, 2) NOT NULL DEFAULT 0,
    56	                refund DECIMAL(10, 2)
    57	            );
    58	
    59	            CREATE TABLE IF NOT EXISTS messages (
    60	                id BIGSERIAL PRIMARY KEY,
    61	                channel VARCHAR(20) NOT NULL,
    62	                recipient VARCHAR(255) NOT NULL,
    63	                subject VARCHAR(255),
    64	                body TEXT NOT NULL
    65	            );
    66	
    67	            CREATE INDEX IF NOT EXISTS idx_reservations_room ON reservations(room_number);
    68	            CREATE INDEX IF NOT EXISTS idx_reservations_check_in ON reservations(check_in);
    69	            CREATE INDEX IF NOT EXISTS idx_reservations_status ON reservations(status);
    70	            """;
    71	
    72	        try (Connection conn = dataSource.getConnection();
    73	             Statement stmt = conn.createStatement()) {
    74	            for (String sql : schema.split(";")) {
    75	                if (!sql.trim().isEmpty()) {
    76	                    stmt.execute(sql.trim());
    77	                }
    78	            }
    79	        } catch (Exception e) {
    80	            throw new RuntimeException("Failed to create database schema", e);
    81	        }
    82	    }
    83	
    84	    public static HikariDataSource getDataSource() {
    85	        if (dataSource == null) {
    86	            initialize();
    87	        }
    88	        return dataSource;
    89	    }
    90	
    91	    public static void close() {
    92	        if (dataSource != null) {
    93	            dataSource.close();
    94	        }
    95	    }
    96	}
