    10	public class EmailService {
    11	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    12	    private static final String LODGE_NAME = "Pousada Maré Alta";
    13	
    14	    public static void sendConfirmationEmail(Reservation reservation) {
    15	        String voucherContent = generateVoucher(reservation);
    16	        String emailBody = generateConfirmationEmailBody(reservation, voucherContent);
    17	
    18	        Message message = new Message(
    19	            "EMAIL",
    20	            reservation.getGuestEmail(),
    21	            "Reserva confirmada - " + LODGE_NAME,
    22	            emailBody
    23	        );
    24	
    25	        MessageRepository.save(message);
    26	    }
    27	
    28	    public static String generateVoucher(Reservation reservation) {
    29	        Room room = RoomRepository.findByNumber(reservation.getRoomNumber());
    30	        String roomType = room.getType().getName();
    31	
    32	        String checkInStr = reservation.getCheckIn().format(DATE_FORMATTER);
    33	        String checkOutStr = reservation.getCheckOut().format(DATE_FORMATTER);
    34	        String nightsText = reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias";
    35	
    36	        StringBuilder voucher = new StringBuilder();
    37	        voucher.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
    38	        voucher.append("Hóspede: ").append(reservation.getGuestName())
    39	            .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
    40	        voucher.append("Quarto: ").append(reservation.getRoomNumber()).append(" (").append(roomType).append(")\n");
    41	        voucher.append("Entrada: ").append(checkInStr).append(" | Saída: ").append(checkOutStr)
    42	            .append(" | ").append(nightsText).append("\n");
    43	        voucher.append("Diárias: R$ ").append(formatCurrency(reservation.getSubtotal())).append("\n");
    44	
    45	        if (reservation.getDiscount() != null && reservation.getDiscount().signum() > 0) {
    46	            voucher.append("Desconto: R$ ").append(formatCurrency(reservation.getDiscount())).append("\n");
    47	        }
    48	
    49	        voucher.append("Total: R$ ").append(formatCurrency(reservation.getTotal()));
    50	
    51	        return voucher.toString();
    52	    }
    53	
    54	    private static String generateConfirmationEmailBody(Reservation reservation, String voucherContent) {
    55	        return "Olá, " + reservation.getGuestName() + "!\n\n" +
    56	               "Sua reserva na " + LODGE_NAME + " está confirmada. Estes são os dados dela:\n\n" +
    57	               voucherContent + "\n\n" +
    58	               "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
    59	               "Até breve!";
    60	    }
    61	
    62	    private static String formatCpf(String cpf) {
    63	        if (cpf == null || cpf.length() != 11) {
    64	            return cpf;
    65	        }
    66	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
    67	               cpf.substring(6, 9) + "-" + cpf.substring(9);
    68	    }
    69	
    70	    private static String formatCurrency(java.math.BigDecimal value) {
    71	        return String.format("%.2f", value);
