    10	public class PricingService {
    11	    public static class PricingResult {
    12	        public int nights;
    13	        public BigDecimal subtotal;
    14	        public BigDecimal discount;
    15	        public BigDecimal total;
    16	
    17	        public PricingResult(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    18	            this.nights = nights;
    19	            this.subtotal = subtotal;
    20	            this.discount = discount;
    21	            this.total = total;
    22	        }
    23	    }
    24	
    25	    public static PricingResult calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
    26	        int nights = DateUtil.countNights(checkIn, checkOut);
    27	
    28	        BigDecimal subtotal = BigDecimal.ZERO;
    29	        LocalDate current = checkIn;
    30	
    31	        while (current.isBefore(checkOut)) {
    32	            BigDecimal nightRate = room.getNightlyRate();
    33	            if (DateUtil.isHighSeason(current)) {
    34	                nightRate = PriceUtil.applyHighSeasonMultiplier(nightRate);
    35	            }
    36	            subtotal = PriceUtil.add(subtotal, nightRate);
    37	            current = current.plusDays(1);
    38	        }
    39	
    40	        BigDecimal discount = PriceUtil.applyPercentage(subtotal, ratePlan.getDiscountRate());
    41	        BigDecimal total = PriceUtil.subtract(subtotal, discount);
    42	
    43	        return new PricingResult(nights, subtotal, discount, total);
    44	    }
    45	}
