    97	        if (reservation == null) {
    98	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found");
    99	        }
   100	
   101	        ReservationStatus status = reservation.getStatus();
   102	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
   103	            throw new ApiException(409, "OPERATION_NOT_ALLOWED",
   104	                "Can only cancel pending or confirmed reservations");
   105	        }
   106	
   107	        reservation.setStatus(ReservationStatus.CANCELLED);
   108	
   109	        BigDecimal refund = calculateRefund(reservation);
