   118	        if (reservation.getStatus() == ReservationStatus.PENDING) {
   119	            return BigDecimal.ZERO;
   120	        }
   121	
   122	        if (reservation.getRatePlan() == RatePlan.STANDARD) {
   123	            return reservation.getAmountPaid();
   124	        }
   125	
   126	        return BigDecimal.ZERO;
