   133	            guestEmail == null || guestEmail.trim().isEmpty() ||
   134	            guestCpf == null || guestCpf.trim().isEmpty() ||
   135	            checkIn == null || checkOut == null ||
   136	            ratePlanStr == null || ratePlanStr.trim().isEmpty()) {
   137	            throw new ApiException(400, "INVALID_REQUEST", "Missing required fields");
   138	        }
   139	
   140	        if (guests < 1) {
   141	            throw new ApiException(400, "INVALID_REQUEST", "At least one guest is required");
