     7	    public static boolean isHighSeason(LocalDate date) {
     8	        Month month = date.getMonth();
     9	        int day = date.getDayOfMonth();
    10	
    11	        if (month == Month.JULY) {
    12	            return true;
    13	        }
    14	
    15	        if (month == Month.DECEMBER) {
    16	            return day >= 15;
    17	        }
    18	
    19	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    20	            return true;
    21	        }
    22	
    23	        return false;
    24	    }
    25	
    26	    public static int countNights(LocalDate checkIn, LocalDate checkOut) {
    27	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    28	    }
