     7	    private static final int SCALE = 2;
     8	    private static final RoundingMode ROUNDING = RoundingMode.HALF_EVEN;
     9	
    10	    public static BigDecimal round(BigDecimal value) {
    11	        return value.setScale(SCALE, ROUNDING);
    12	    }
    13	
    14	    public static BigDecimal multiply(BigDecimal a, BigDecimal b) {
    15	        return round(a.multiply(b));
    16	    }
    17	
    18	    public static BigDecimal add(BigDecimal a, BigDecimal b) {
    19	        return round(a.add(b));
    20	    }
    21	
