    13	public class ReservationService {
    14	    public static Reservation createReservation(int roomNumber, String guestName, String guestEmail,
    15	                                                String guestCpf, LocalDate checkIn, LocalDate checkOut,
    16	                                                int guests, String ratePlanStr) {
    17	        validateCreateRequest(roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlanStr);
    18	
    19	        Room room = RoomRepository.findByNumber(roomNumber);
    20	        if (room == null) {
    21	            throw new ApiException(404, "ROOM_NOT_FOUND", "Room not found");
    22	        }
    23	
    24	        if (guests > room.getCapacity()) {
    25	            throw new ApiException(422, "CAPACITY_EXCEEDED", "Too many guests for this room");
    26	        }
    27	
    28	        if (!ReservationRepository.isRoomAvailable(roomNumber, checkIn, checkOut)) {
    29	            throw new ApiException(409, "ROOM_UNAVAILABLE", "Room is not available for these dates");
    30	        }
    31	
    32	        RatePlan ratePlan = RatePlan.fromString(ratePlanStr);
    33	        Reservation reservation = new Reservation(roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan);
    34	
    35	        PricingService.PricingResult pricing = PricingService.calculatePrice(room, checkIn, checkOut, ratePlan);
    36	        reservation.setNights(pricing.nights);
    37	        reservation.setSubtotal(pricing.subtotal);
    38	        reservation.setDiscount(pricing.discount);
    39	        reservation.setTotal(pricing.total);
    40	
    41	        return ReservationRepository.save(reservation);
